UPDATE ha_session
SET
    snapshot_id = #{snapshotId}
WHERE
    owner_key = #{ownerKey}
    AND session_id = #{sessionId}
    AND (
        snapshot_id = #{expectedSnapshotId}
        OR (
            snapshot_id IS NULL
            AND #{expectedSnapshotId} IS NULL
        )
    )

UPDATE ha_session
SET
    snapshot_id = #{snapshotId}
WHERE
    owner_key = #{ownerKey}
    AND session_id = #{sessionId}
    AND active_turn_id = #{activeTurnId}
    AND (
        snapshot_id = #{expectedSnapshotId}
        OR (
            snapshot_id IS NULL
            AND #{expectedSnapshotId} IS NULL
        )
    )
    AND EXISTS (
        SELECT
            1
        FROM
            ha_turn t
        WHERE
            t.owner_key = ha_session.owner_key
            AND t.turn_id = #{turnId}
            AND t.executor_id = #{executorId}
            AND t.status IN ('RUNNING', 'CANCELLING')
            AND t.lease_expires_at > CURRENT_TIMESTAMP(6)
    )

UPDATE ha_session
SET
    snapshot_id = #{snapshotId}
WHERE
    owner_key = #{ownerKey}
    AND session_id = #{sessionId}
